    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

import numpy as np
from scipy import stats

# --- filters ---
sale_mask = df['row_kind'] == 'sale'
sale_ret_mask = df['row_kind'].isin(['sale', 'return'])
usd_mask = df['Currency'] == 'USD'

sale_usd = df[sale_mask & usd_mask].copy()
sale_ret_usd = df[sale_ret_mask & usd_mask].copy()

# --- EDA ---
try:
    metric_cols = ['Lineitem quantity', 'Lineitem price', 'Discount Amount', 'Total']
    eda = {}
    for c in metric_cols:
        s = df[c].dropna()
        eda[c] = {
            "mean": float(s.mean()), "std": float(s.std()),
            "min": float(s.min()), "max": float(s.max()),
            "median": float(s.median()), "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception:
    pass

# --- CORRELATIONS (beyond target pairs, computed separately) ---
try:
    num_df = sale_usd[metric_cols].dropna()
    corr_dict = {}
    for i, c1 in enumerate(metric_cols):
        for c2 in metric_cols[i+1:]:
            r, _ = stats.pearsonr(num_df[c1], num_df[c2])
            if abs(r) >= 0.2:
                corr_dict[f"{c1}__{c2}"] = round(float(r), 4)
    result['correlations'] = corr_dict
except Exception:
    pass

# --- SEGMENTATION ---
try:
    segs = []
    seg_cols = ['Financial Status', 'Shipping Country', 'Currency']
    metric_map = {
        'Lineitem quantity': 'sum',
        'Lineitem price': 'mean',
        'Discount Amount': 'sum',
        'Total': 'sum'
    }
    base = sale_usd.drop_duplicates(subset=['Name', 'Lineitem sku'])

    for sc in seg_cols:
        for mc, agg in metric_map.items():
            try:
                grp = base.groupby(sc)[mc]
                if agg == 'sum':
                    res = grp.sum()
                else:
                    res = grp.mean()
                top = res.nlargest(10)
                segs.append({
                    "segment_column": sc, "metric_column": mc,
                    "aggregation": agg, "label": None,
                    "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in top.items()]
                })
            except Exception:
                pass

    # return_rate ratio
    try:
        ret_mask2 = df['row_kind'].isin(['return', 'refunded']) & usd_mask
        ret_df = df[ret_mask2].copy()
        gross_sales = (sale_usd['Lineitem quantity'] * sale_usd['Lineitem price']).sum()
        ret_val = (ret_df['Lineitem quantity'].abs() * ret_df['Lineitem price'].abs()).sum()
        rr = float(ret_val / gross_sales) if gross_sales > 0 else 0.0
        segs.append({
            "segment_column": "Financial Status", "metric_column": "Lineitem price",
            "aggregation": "ratio", "label": "return_rate",
            "results": [{"name": "overall", "value": round(rr, 4)}]
        })
    except Exception:
        pass

    result['segments'] = segs
except Exception:
    pass

# --- ANOMALIES ---
try:
    anomalies = []
    anom_cols = ['Lineitem quantity', 'Lineitem price', 'Discount Amount', 'Total']
    anom_df = sale_usd[anom_cols].copy()
    total_cap = 25

    for col in anom_cols:
        if total_cap <= 0:
            break
        s = anom_df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0.0
        if abs(skew) > 2:
            shift = max(0.0, -s.min())
            s_work = np.log1p(s + shift)
        else:
            s_work = s.copy()

        q1, q3 = s_work.quantile(0.25), s_work.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr

        mask_ext = (s_work < lo3) | (s_work > hi3)
        if mask_ext.sum() / len(s_work) > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": "heavy-tailed distribution",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme-value flagging skipped"
            })
            continue

        flagged = s_work[mask_ext]
        orig_vals = s[mask_ext]

        if abs(skew) > 2:
            lo3_orig = float(np.expm1(lo3) - shift)
            hi3_orig = float(np.expm1(hi3) - shift)
        else:
            lo3_orig, hi3_orig = float(lo3), float(hi3)

        exp_range = f"[{lo3_orig:.2f}, {hi3_orig:.2f}]"

        for idx in flagged.index[:total_cap]:
            v_work = s_work.loc[idx]
            v_orig = float(orig_vals.loc[idx])
            if v_work > hi5 or v_work < lo5:
                sev = "critical"
            elif v_work > hi4 or v_work < lo4:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col, "row_index": int(idx),
                "value": round(v_orig, 4),
                "expected_range": exp_range,
                "severity": sev,
                "explanation": f"{col} value {round(v_orig, 4)} lies outside expected range {exp_range}"
            })
            total_cap -= 1
            if total_cap <= 0:
                break

    result['anomalies'] = anomalies
except Exception:
    pass

# --- TRENDS (7d rolling on sale+USD rows) ---
try:
    trend_df = sale_usd.copy()
    trend_df['date'] = pd.to_datetime(trend_df['Created at'])
    trend_df = trend_df.set_index('date').sort_index()

    trends = []
    roll_metrics = {
        'Lineitem quantity': 'sum',
        'Lineitem price': 'mean',
        'Total': 'sum'
    }
    for col, agg in roll_metrics.items():
        try:
            daily = trend_df[col].resample('D').sum() if agg == 'sum' else trend_df[col].resample('D').mean()
            rolled = daily.rolling(7).mean().dropna()
            if len(rolled) < 2:
                continue
            first_half = rolled.iloc[:len(rolled)//2].mean()
            second_half = rolled.iloc[len(rolled)//2:].mean()
            pct = float((second_half - first_half) / first_half * 100) if first_half != 0 else 0.0
            direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
            trends.append({
                "column": col, "period": "7d_rolling",
                "direction": direction, "pct_change": round(pct, 2), "segment": None
            })
        except Exception:
            pass
    result['trends'] = trends
except Exception:
    pass

# --- FORECASTING (simple linear extrapolation on monthly Total) ---
try:
    fc_df = sale_usd.copy()
    fc_df['date'] = pd.to_datetime(fc_df['Created at'])
    fc_df['month'] = fc_df['date'].dt.to_period('M')
    monthly = fc_df.drop_duplicates(subset=['Name'])[['month', 'Total']].groupby('month')['Total'].sum().sort_index()

    if len(monthly) >= 3:
        x = np.arange(len(monthly))
        y = monthly.values.astype(float)
        slope, intercept, _, _, _ = stats.linregress(x, y)
        forecast_points = []
        last_period = monthly.index[-1]
        for i in range(1, 4):
            next_period = last_period + i
            pred = float(intercept + slope * (len(monthly) - 1 + i))
            forecast_points.append({"period": str(next_period), "value": round(pred, 2)})
        result['forecast_points'] = forecast_points
except Exception:
    pass

# --- ASSUMPTIONS ---
result['assumptions'] = [
    "EDA describes all rows as loaded; sales figures use sale+USD rows only.",
